import React from 'react';
import { NavLink } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';

const Sidebar = ({ userRole }) => {
  const { currentUser } = useAuth();

  const adminLinks = [
    { to: '/admin', text: 'Tableau de Bord', icon: '📊' },
    { to: '/admin/users', text: 'Gestion des Utilisateurs', icon: '👥' },
    { to: '/admin/statistics', text: 'Statistiques', icon: '📈' },
  ];

  const professorLinks = [
    { to: '/professor', text: 'Tableau de Bord', icon: '📊' },
    { to: '/professor/create-quiz', text: 'Créer un Quiz', icon: '➕' },
    { to: '/professor/manage-quiz', text: 'Gérer les Quiz', icon: '📝' },
    { to: '/professor/results', text: 'Analyse des Résultats', icon: '📊' },
  ];

  const studentLinks = [
    { to: '/student', text: 'Tableau de Bord', icon: '📊' },
    { to: '/student/results', text: 'Mes Résultats', icon: '📄' },
  ];

  // Determine which links to show based on user role
  let links = [];
  switch (userRole) {
    case 'admin':
      links = adminLinks;
      break;
    case 'professor':
      links = professorLinks;
      break;
    case 'student':
      links = studentLinks;
      break;
    default:
      links = [];
  }

  return (
    <div className="sidebar">
      <div className="user-info">
        {currentUser && (
          <>
            <div className="user-avatar">{currentUser.name.charAt(0).toUpperCase()}</div>
            <h3>{currentUser.name}</h3>
            <p>{userRole.charAt(0).toUpperCase() + userRole.slice(1)}</p>
          </>
        )}
      </div>
      <nav className="sidebar-nav">
        <ul>
          {links.map((link) => (
            <li key={link.to}>
              <NavLink to={link.to} end={link.to.split('/').length === 2}>
                <span className="icon">{link.icon}</span>
                {link.text}
              </NavLink>
            </li>
          ))}
        </ul>
      </nav>
    </div>
  );
};

export default Sidebar;
